impl<'a, C: Catalog> Planner<'a, C> {
    /// Creates a new planner.
    pub fn new(catalog: &'a C) -> Self {
        Planner { catalog }
    }

    /// Builds a plan for an AST statement.
    pub fn build(&mut self, statement: ast::Statement) -> Result<Plan> {
        match statement {
            ast::Statement::Begin { .. } => errinput!("BEGIN not implemented in planner"),
            ast::Statement::Commit => errinput!("COMMIT not implemented in planner"),
            ast::Statement::Rollback => errinput!("ROLLBACK not implemented in planner"),
            ast::Statement::Explain(stmt) => {
                let plan = self.build(*stmt)?;
                Ok(Plan::Explain(Box::new(plan)))
            }
            ast::Statement::CreateTable { name, columns } => self.build_create_table(name, columns),
            ast::Statement::DropTable { name, if_exists } => self.build_drop_table(name, if_exists),
            ast::Statement::Delete { table, r#where } => self.build_delete(table, r#where),
            ast::Statement::Insert { table, columns, values } => self.build_insert(table, columns, values),
            ast::Statement::Update { table, set, r#where } => self.build_update(table, set, r#where),
            ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit } => {
                self.build_select(select, from, r#where, group_by, having, order_by, offset, limit)
            }
        }
    }

    /// Builds a CREATE TABLE plan.
    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut table_columns = Vec::new();
        let mut primary_key_index = 0;

        for (i, col) in columns.into_iter().enumerate() {
            let default_value = if let Some(default_expr) = col.default {
                Some(self.build_constant_value(default_expr)?)
            } else {
                None
            };

            table_columns.push(Column {
                name: col.name,
                datatype: col.datatype,
                nullable: col.nullable.unwrap_or(true),
                default: default_value,
                unique: col.unique,
                index: col.index,
                references: col.references,
            });

            if col.primary_key {
                primary_key_index = i;
            }
        }

        let table = Table {
            name,
            primary_key: primary_key_index,
            columns: table_columns,
        };

        Ok(Plan::CreateTable { schema: table })
    }

    /// Builds a DROP TABLE plan.
    fn build_drop_table(&self, name: String, if_exists: bool) -> Result<Plan> {
        Ok(Plan::DropTable { name, if_exists })
    }

    /// Builds a DELETE plan.
    fn build_delete(&self, table: String, r#where: Option<ast::Expression>) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;
        let primary_key = table_schema.primary_key;

        let source = if let Some(expr) = r#where {
            let mut scope = Scope::from_table(&table_schema)?;
            scope.add_table(&table_schema, Some(&table))?;
            let filter = self.build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: table_schema.clone(),
                    filter: None,
                    alias: None,
                }),
                predicate: filter,
            }
        } else {
            Node::Scan {
                table: table_schema,
                filter: None,
                alias: None,
            }
        };

        Ok(Plan::Delete { table, primary_key, source: Box::new(source) })
    }

    /// Builds an INSERT plan.
    fn build_insert(
        &self,
        table: String,
        columns: Option<Vec<String>>,
        values: Vec<Vec<ast::Expression>>,
    ) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;

        // Build column map
        let column_map = if let Some(col_names) = &columns {
            let mut map = HashMap::new();
            for (i, col_name) in col_names.iter().enumerate() {
                if let Some(idx) = table_schema.columns.iter().position(|c| &c.name == col_name) {
                    map.insert(i, idx);
                }
            }
            Some(map)
        } else {
            None
        };

        // Build VALUES node
        let mut rows = Vec::new();
        for value_row in values {
            let mut expr_row = Vec::new();
            for expr in value_row {
                expr_row.push(self.build_constant_value(expr)?);
            }
            rows.push(expr_row);
        }

        let source = Node::Values { rows };

        Ok(Plan::Insert { 
            table: table_schema, 
            column_map, 
            source: Box::new(source) 
        })
    }

    /// Builds an UPDATE plan.
    fn build_update(
        &self,
        table: String,
        set: BTreeMap<String, Option<ast::Expression>>,
        r#where: Option<ast::Expression>,
    ) -> Result<Plan> {
        let table_schema = self.catalog.must_get_table(&table)?;
        let primary_key = table_schema.primary_key;

        // Build expressions for SET clause
        let mut expressions = Vec::new();
        for (col_name, expr_opt) in set {
            if let Some(expr) = expr_opt {
                if let Some(col_idx) = table_schema.columns.iter().position(|c| &c.name == col_name) {
                    // We'll build the expression later with proper scope
                    expressions.push((col_idx, self.build_expression_placeholder(expr)));
                }
            }
        }

        let source = if let Some(expr) = r#where {
            let mut scope = Scope::from_table(&table_schema)?;
            scope.add_table(&table_schema, Some(&table))?;
            let filter = self.build_expression(expr, &scope)?;
            Node::Filter {
                source: Box::new(Node::Scan {
                    table: table_schema.clone(),
                    filter: None,
                    alias: None,
                }),
                predicate: filter,
            }
        } else {
            Node::Scan {
                table: table_schema.clone(),
                filter: None,
                alias: None,
            }
        };

        Ok(Plan::Update { 
            table: table_schema, 
            primary_key, 
            source: Box::new(source),
            expressions,
        })
    }

    /// Builds a placeholder expression for UPDATE (will be fixed later)
    fn build_expression_placeholder(&self, expr: ast::Expression) -> Expression {
        // For now, just convert literals
        match expr {
            ast::Expression::Literal(lit) => {
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                };
                Expression::Value(value)
            }
            _ => Expression::Value(Value::Null), // placeholder
        }
    }

    /// Builds a SELECT plan.
    #[allow(clippy::too_many_arguments)]
    fn build_select(
        &self,
        select: Vec<(ast::Expression, Option<String>)>,
        from: Vec<ast::From>,
        r#where: Option<ast::Expression>,
        group_by: Vec<ast::Expression>,
        having: Option<ast::Expression>,
        order_by: Vec<(ast::Expression, ast::Direction)>,
        offset: Option<ast::Expression>,
        limit: Option<ast::Expression>,
    ) -> Result<Plan> {
        // If no FROM clause, check if we have constant expressions
        if from.is_empty() {
            // For constant selects, create a VALUES node with a blank row
            let mut scope = Scope::new();
            let mut expressions = Vec::new();
            let mut aliases = Vec::new();

            for (expr, alias) in &select {
                let built_expr = self.build_expression(expr.clone(), &scope)?;
                expressions.push(built_expr);
                aliases.push(match alias {
                    Some(s) => Label::Unqualified(s.clone()),
                    None => Label::None,
                });
            }

            let source = Node::Values { rows: vec![vec![]] }; // blank row

            let node = if expressions.is_empty() {
                Node::Nothing { columns: aliases }
            } else {
                Node::Projection {
                    source: Box::new(source),
                    expressions,
                    aliases,
                }
            };

            return Ok(Plan::Select(node));
        }

        // Build FROM clause
        let mut scope = Scope::new();
        let mut node = self.build_from_clause(from, &mut scope)?;

        // Build WHERE clause
        if let Some(expr) = r#where {
            let filter = self.build_expression(expr, &scope)?;
            node = Node::Filter {
                source: Box::new(node),
                predicate: filter,
            };
        }

        // Build GROUP BY and aggregate
        if !group_by.is_empty() {
            let mut group_by_exprs = Vec::new();
            for expr in &group_by {
                group_by_exprs.push(self.build_expression(expr.clone(), &scope)?);
            }

            // Collect aggregates
            let mut aggregates = Vec::new();
            for (expr, _) in &select {
                self.collect_aggregate_functions(expr, &mut aggregates, &scope)?;
            }
            if let Some(ref expr) = having {
                self.collect_aggregate_functions(expr, &mut aggregates, &scope)?;
            }
            for (expr, _) in &order_by {
                self.collect_aggregate_functions(expr, &mut aggregates, &scope)?;
            }

            let agg_exprs: Vec<Aggregate> = aggregates.into_iter()
                .map(|e| self.build_aggregate_function(e, &scope))
                .collect::<Result<Vec<_>>>()?;

            node = Node::Aggregate {
                source: Box::new(node),
                group_by: group_by_exprs,
                aggregates: agg_exprs,
            };
        }

        // Build SELECT expressions
        let mut expressions = Vec::new();
        let mut aliases = Vec::new();
        for (expr, alias) in &select {
            expressions.push(self.build_expression(expr.clone(), &scope)?);
            aliases.push(match alias {
                Some(s) => Label::Unqualified(s.clone()),
                None => Label::None,
            });
        }

        node = Node::Projection {
            source: Box::new(node),
            expressions,
            aliases,
        };

        // Build HAVING clause (after aggregation)
        if let Some(expr) = having {
            let filter = self.build_expression(expr, &scope)?;
            node = Node::Filter {
                source: Box::new(node),
                predicate: filter,
            };
        }

        // Build ORDER BY
        if !order_by.is_empty() {
            let mut key = Vec::new();
            for (expr, dir) in &order_by {
                let built_expr = self.build_expression(expr.clone(), &scope)?;
                let direction = match dir {
                    ast::Direction::Ascending => Direction::Ascending,
                    ast::Direction::Descending => Direction::Descending,
                };
                key.push((built_expr, direction));
            }

            node = Node::Order {
                source: Box::new(node),
                key,
            };
        }

        // Build OFFSET
        if let Some(expr) = offset {
            let offset_val = self.build_constant_value(expr)?;
            if let Value::Integer(n) = offset_val {
                node = Node::Offset {
                    source: Box::new(node),
                    offset: n as usize,
                };
            }
        }

        // Build LIMIT
        if let Some(expr) = limit {
            let limit_val = self.build_constant_value(expr)?;
            if let Value::Integer(n) = limit_val {
                node = Node::Limit {
                    source: Box::new(node),
                    limit: n as usize,
                };
            }
        }

        Ok(Plan::Select(node))
    }

    /// Collects aggregate functions from an expression
    fn collect_aggregate_functions(&self, expr: &ast::Expression, aggregates: &mut Vec<ast::Expression>, scope: &Scope) -> Result<()> {
        match expr {
            ast::Expression::Function(name, args) if self.is_aggregate_function_name(name) => {
                aggregates.push(expr.clone());
            }
            ast::Expression::Operator(op) => {
                use ast::Operator::*;
                match op {
                    And(lhs, rhs) | Or(lhs, rhs) | Equal(lhs, rhs) | GreaterThan(lhs, rhs) 
                    | GreaterThanOrEqual(lhs, rhs) | LessThan(lhs, rhs) | LessThanOrEqual(lhs, rhs)
                    | NotEqual(lhs, rhs) | Add(lhs, rhs) | Divide(lhs, rhs) | Exponentiate(lhs, rhs)
                    | Multiply(lhs, rhs) | Remainder(lhs, rhs) | Subtract(lhs, rhs) | Like(lhs, rhs) => {
                        self.collect_aggregate_functions(lhs, aggregates, scope)?;
                        self.collect_aggregate_functions(rhs, aggregates, scope)?;
                    }
                    Not(e) | Factorial(e) | Identity(e) | Negate(e) | Is(e, _) => {
                        self.collect_aggregate_functions(e, aggregates, scope)?;
                    }
                }
            }
            ast::Expression::Function(_, args) => {
                for arg in args {
                    self.collect_aggregate_functions(arg, aggregates, scope)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    /// Checks if a function name is an aggregate function
    fn is_aggregate_function_name(&self, name: &str) -> bool {
        matches!(name.to_lowercase().as_str(), 
            "count" | "sum" | "avg" | "min" | "max" | "median" | "string_agg"
        )
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(&self, expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        let ast::Expression::Function(name, args) = expr else {
            return errinput!("expected aggregate function");
        };

        let name_lower = name.to_lowercase();

        match name_lower.as_str() {
            "count" => {
                let arg = if args.is_empty() {
                    ast::Expression::Literal(ast::Literal::Null)
                } else {
                    args.into_iter().next().unwrap()
                };
                Ok(Aggregate::Count(self.build_expression(arg, scope)?))
            }
            "sum" => {
                let arg = args.into_iter().next().ok_or_else(|| errinput!("sum requires one argument"))?;
                Ok(Aggregate::Sum(self.build_expression(arg, scope)?))
            }
            "avg" => {
                let arg = args.into_iter().next().ok_or_else(|| errinput!("avg requires one argument"))?;
                Ok(Aggregate::Average(self.build_expression(arg, scope)?))
            }
            "min" => {
                let arg = args.into_iter().next().ok_or_else(|| errinput!("min requires one argument"))?;
                Ok(Aggregate::Min(self.build_expression(arg, scope)?))
            }
            "max" => {
                let arg = args.into_iter().next().ok_or_else(|| errinput!("max requires one argument"))?;
                Ok(Aggregate::Max(self.build_expression(arg, scope)?))
            }
            "median" => {
                let arg = args.into_iter().next().ok_or_else(|| errinput!("median requires one argument"))?;
                Ok(Aggregate::Median(self.build_expression(arg, scope)?))
            }
            "string_agg" => {
                if args.len() != 2 {
                    return errinput!("string_agg requires two arguments");
                }
                let mut it = args.into_iter();
                let arg1 = it.next().unwrap();
                let arg2 = it.next().unwrap();
                Ok(Aggregate::StringAgg(
                    self.build_expression(arg1, scope)?,
                    self.build_expression(arg2, scope)?
                ))
            }
            _ => errinput!("unknown aggregate function: {}", name),
        }
    }

    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        let mut node = self.build_from(from[0].clone(), scope)?;

        for from_item in from.into_iter().skip(1) {
            let join_node = self.build_from(from_item, scope)?;
            node = Node::NestedLoopJoin {
                left: Box::new(node),
                right: Box::new(join_node),
                predicate: None,
                outer: false,
            };
        }

        Ok(node)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.must_get_table(&name)?;
                let table_name = alias.clone().unwrap_or_else(|| name.clone());

                let mut table_scope = Scope::from_table(&table)?;
                table_scope.add_table(&table, Some(&table_name))?;

                // Merge with parent scope
                parent_scope.merge(table_scope)?;

                Ok(Node::Scan {
                    table,
                    filter: None,
                    alias,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let left_node = self.build_from(*left, parent_scope)?;
                let right_node = self.build_from(*right, parent_scope)?;

                let outer = r#type.is_outer();
                let join_predicate = if let Some(expr) = predicate {
                    Some(self.build_expression(expr, parent_scope)?)
                } else {
                    None
                };

                Ok(Node::NestedLoopJoin {
                    left: Box::new(left_node),
                    right: Box::new(right_node),
                    predicate: join_predicate,
                    outer,
                })
            }
        }
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
            ast::Expression::All => errinput!("unsupported use of *"),
            ast::Expression::Column(table, name) => {
                let index = scope.lookup_column(table.as_deref(), &name)?;
                Ok(Expression::Column(index))
            }
            ast::Expression::Literal(lit) => {
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                };
                Ok(Expression::Value(value))
            }
            ast::Expression::Function(name, args) => {
                let args = args.into_iter()
                    .map(|arg| Self::build_expression(arg, scope))
                    .collect::<Result<Vec<_>>>()?;
                Ok(Expression::Function(name, args))
            }
            ast::Expression::Operator(op) => {
                Self::build_operator(op, scope)
            }
        }
    }

    /// Builds an operator expression from an AST operator.
    fn build_operator(op: ast::Operator, scope: &Scope) -> Result<Expression> {
        use ast::Operator::*;

        match op {
            And(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::And(Box::new(lhs), Box::new(rhs)))
            }
            Not(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Not(Box::new(expr)))
            }
            Or(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Or(Box::new(lhs), Box::new(rhs)))
            }
            Equal(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Equal(Box::new(lhs), Box::new(rhs)))
            }
            GreaterThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::GreaterThan(Box::new(lhs), Box::new(rhs)))
            }
            GreaterThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)))
            }
            Is(expr, lit) => {
                let expr = Self::build_expression(*expr, scope)?;
                let value = match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Float(f) if f.is_nan() => Value::Float(f64::NAN),
                    _ => return errinput!("IS only supports NULL and NaN"),
                };
                Ok(Expression::Is(Box::new(expr), value))
            }
            LessThan(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::LessThan(Box::new(lhs), Box::new(rhs)))
            }
            LessThanOrEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::LessThanOrEqual(Box::new(lhs), Box::new(rhs)))
            }
            NotEqual(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::NotEqual(Box::new(lhs), Box::new(rhs)))
            }
            Add(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Add(Box::new(lhs), Box::new(rhs)))
            }
            Divide(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Divide(Box::new(lhs), Box::new(rhs)))
            }
            Exponentiate(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Exponentiate(Box::new(lhs), Box::new(rhs)))
            }
            Factorial(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Factorial(Box::new(expr)))
            }
            Identity(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Identity(Box::new(expr)))
            }
            Multiply(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Multiply(Box::new(lhs), Box::new(rhs)))
            }
            Negate(expr) => {
                let expr = Self::build_expression(*expr, scope)?;
                Ok(Expression::Negate(Box::new(expr)))
            }
            Remainder(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Remainder(Box::new(lhs), Box::new(rhs)))
            }
            Subtract(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Subtract(Box::new(lhs), Box::new(rhs)))
            }
            Like(lhs, rhs) => {
                let lhs = Self::build_expression(*lhs, scope)?;
                let rhs = Self::build_expression(*rhs, scope)?;
                Ok(Expression::Like(Box::new(lhs), Box::new(rhs)))
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        match expr {
            ast::Expression::Literal(lit) => {
                Ok(match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                })
            }
            _ => errinput!("expression must be constant"),
        }
    }
}
